import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { withGlass } from "@/lib/glass/context";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-4xl border border-transparent bg-clip-padding font-medium text-sm outline-none transition-[box-shadow,transform] focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-transparent dark:hover:bg-input/30",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 dark:hover:bg-destructive/30",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-9 gap-1.5 px-3 has-data-[icon=inline-start]:ps-2.5 has-data-[icon=inline-end]:pe-2.5",
        xs: "h-6 gap-1 px-2.5 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1 px-3 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2",
        lg: "h-10 gap-1.5 px-4 has-data-[icon=inline-start]:ps-3 has-data-[icon=inline-end]:pe-3",
        icon: "size-9",
        "icon-xs": "size-6 [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function ButtonImplementation({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

const Button = withGlass(ButtonImplementation, "control");

export { Button, buttonVariants };

"use client";

import { cn } from "cn";
import { ChevronRight, FileCode2 } from "lucide-react";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import {
  useHighlightedLines,
  useStreamingScroll,
} from "@/hooks/use-viewer-code";
import { useViewerTheme } from "@/hooks/use-viewer-theme";
import { useGlassEnabled } from "@/lib/glass/context";
import { ViewerCopyButton, ViewerStatus } from "@/lib/viewer/controls";
import type { ThemedToken } from "@/lib/viewer/shiki";
import { Button } from "@/components/ui/button";
import { GlassSurface } from "@/components/ui/glass";
import { Skeleton } from "@/components/ui/skeleton";

interface CodeLine {
  index: number;
  tokens: ThemedToken[];
  content: string;
  indent: number;
  isFoldable: boolean;
  foldEnd: number;
}

export type CodeViewerLabels = {
  copy: string;
  loading: string;
  error: string;
  empty: string;
  expand: string;
  collapse: string;
  writing: string;
  ready: string;
  copied: string;
  copyFailed: string;
};

export interface CodeViewerProps {
  readonly variant?: "default" | "plain";
  readonly code: string;
  readonly lang?: string;
  readonly theme?: "light" | "dark";
  readonly className?: string;
  readonly glass?: boolean;
  readonly title?: ReactNode;
  readonly labels?: Partial<CodeViewerLabels>;
  readonly status?: "streaming" | "complete";
  readonly showLineNumbers?: boolean;
  readonly highlightLines?: number[];
  readonly maxHeight?: number;
  readonly wrap?: boolean;
  readonly copyable?: boolean;
}

const DEFAULT_CODE_VIEWER_LABELS: CodeViewerLabels = {
  copy: "Copy code",
  loading: "Loading...",
  error: "Unable to highlight code",
  empty: "No code",
  expand: "Expand",
  collapse: "Collapse",
  writing: "Writing",
  ready: "Ready",
  copied: "Copied",
  copyFailed: "Copy failed",
};

const EMPTY_LINES: number[] = [];

export function CodeViewer({
  code,
  variant = "default",
  lang = "typescript",
  theme,
  className,
  glass,
  title,
  labels,
  status = "complete",
  showLineNumbers = true,
  highlightLines = EMPTY_LINES,
  maxHeight = 280,
  wrap = false,
  copyable = true,
}: Readonly<CodeViewerProps>) {
  const rootRef = useRef<HTMLDivElement>(null);
  const glassEnabled = useGlassEnabled(glass);
  const text = { ...DEFAULT_CODE_VIEWER_LABELS, ...labels };
  const { resolvedTheme: appTheme } = useViewerTheme(rootRef);
  const resolvedTheme = theme ?? appTheme;
  const reduceMotion = useReducedMotion() ?? false;
  const viewportRef = useRef<HTMLDivElement>(null);
  const {
    lines: tokenLines,
    failed: highlightError,
    loading: highlightLoading,
  } = useHighlightedLines(code, lang, resolvedTheme);
  const [collapsed, setCollapsed] = useState<Set<number>>(new Set());
  const highlighted = useMemo(() => new Set(highlightLines), [highlightLines]);
  const streaming = status === "streaming";
  const [hasStreamed, setHasStreamed] = useState(streaming);
  if (streaming && !hasStreamed) setHasStreamed(true);

  const lines = useMemo<CodeLine[]>(() => {
    const parsed = (code ? code.split("\n") : []).map((content, index) => {
      const indent = content.search(/[^ \t]/);
      return {
        index,
        tokens: tokenLines[index] ?? [],
        content,
        indent: indent === -1 ? content.length : indent,
        isFoldable: false,
        foldEnd: index,
      };
    });

    for (let index = 0; index < parsed.length - 1; index++) {
      const line = parsed[index];
      const lastChar = line.content.trimEnd().at(-1);
      if (lastChar !== "{" && lastChar !== "[" && lastChar !== "(") continue;
      let firstContent = index + 1;
      while (
        firstContent < parsed.length &&
        !parsed[firstContent].content.trim()
      )
        firstContent++;
      if (
        firstContent === parsed.length ||
        parsed[firstContent].indent <= line.indent
      )
        continue;
      let nextOutdentIndex = -1;
      for (
        let lineIndex = firstContent;
        lineIndex < parsed.length;
        lineIndex++
      ) {
        if (
          !parsed[lineIndex].content.trim() ||
          parsed[lineIndex].indent > line.indent
        )
          continue;
        nextOutdentIndex = lineIndex;
        break;
      }
      line.isFoldable = true;
      line.foldEnd =
        nextOutdentIndex === -1 ? parsed.length - 1 : nextOutdentIndex - 1;
    }

    return parsed;
  }, [code, tokenLines]);

  const hiddenLines = useMemo(
    () =>
      new Set(
        Array.from(collapsed).flatMap((foldLine) => {
          const line = lines[foldLine];
          if (!line) return [];
          return Array.from(
            { length: line.foldEnd - foldLine },
            (_, index) => foldLine + index + 1,
          );
        }),
      ),
    [collapsed, lines],
  );

  useEffect(() => {
    void code;
    setCollapsed(new Set());
  }, [code]);

  useStreamingScroll(viewportRef, code, streaming);

  function toggleFold(lineIndex: number) {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(lineIndex)) next.delete(lineIndex);
      else next.add(lineIndex);
      return next;
    });
  }

  const showSkeleton = highlightLoading && !streaming && !hasStreamed;
  return (
    <GlassSurface
      ref={rootRef}
      glass={glassEnabled}
      data-slot="code-viewer"
      data-state={status}
      aria-busy={streaming}
      className={cn(
        variant === "plain"
          ? "relative min-w-0 overflow-hidden text-foreground text-sm"
          : "flex min-h-0 w-full flex-col overflow-hidden rounded-2xl bg-muted/80 text-foreground text-sm ring-1 ring-border",
        className,
      )}
    >
      {variant === "default" ? (
        <div className="flex min-h-10 shrink-0 flex-wrap items-center gap-x-2 gap-y-1 border-border/70 border-b bg-muted/80 px-3 py-1">
          <FileCode2
            aria-hidden="true"
            className="size-3.5 shrink-0 text-muted-foreground/70"
          />
          {title ? (
            <span className="min-w-0 truncate font-medium font-mono text-foreground/80 text-sm">
              {title}
            </span>
          ) : null}
          <span className="font-medium text-muted-foreground/65 text-sm">
            {lang}
          </span>
          <span className="ml-auto">
            <ViewerStatus
              streaming={streaming}
              loading={highlightLoading}
              failed={highlightError}
              reducedMotion={reduceMotion}
              labels={text}
            />
          </span>
          {copyable ? <ViewerCopyButton value={code} labels={text} /> : null}
        </div>
      ) : (
        <div className="absolute end-1 top-1 z-10">
          {copyable && <ViewerCopyButton value={code} labels={text} />}
          <span className="sr-only">
            <ViewerStatus
              streaming={streaming}
              loading={highlightLoading}
              failed={highlightError}
              reducedMotion={reduceMotion}
              labels={text}
            />
          </span>
        </div>
      )}
      <div
        ref={viewportRef}
        tabIndex={0}
        role={streaming ? "log" : undefined}
        aria-live={streaming ? "polite" : undefined}
        className="min-h-0 flex-1 overflow-auto py-2 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
        style={{ maxHeight }}
      >
        {showSkeleton && (
          <div role="status" aria-label={text.loading} className="grid px-4">
            {Array.from(
              {
                length: Math.min(
                  lines.length,
                  Math.max(1, Math.ceil(maxHeight / 20)),
                ),
              },
              (_, index) => index + 1,
            ).map((lineNumber) => (
              <Skeleton
                key={lineNumber}
                glass={false}
                className="h-5 w-3/4 rounded-md"
              />
            ))}
            <pre className="sr-only">{code}</pre>
          </div>
        )}
        {!showSkeleton && lines.length > 0 && (
          <table
            className={cn(
              "w-full border-collapse font-mono text-foreground/85 text-sm leading-5",
              wrap ? "table-fixed" : "min-w-max",
            )}
          >
            <tbody>
              {lines.map((line) => {
                if (hiddenLines.has(line.index)) return null;
                const isFolded = collapsed.has(line.index);
                return (
                  <tr
                    key={line.index}
                    className={cn(
                      "group/line h-5 hover:bg-accent/40",
                      highlighted.has(line.index + 1) &&
                        "bg-[var(--code-highlight-bg,color-mix(in_oklch,var(--primary)_10%,transparent))]",
                    )}
                  >
                    {showLineNumbers ? (
                      <td className="w-11 select-none pr-2 text-right text-muted-foreground/50 tabular-nums">
                        {line.index + 1}
                      </td>
                    ) : null}
                    <td className="w-5 select-none">
                      {line.isFoldable ? (
                        <Button
                          variant="ghost"
                          size="icon-xs"
                          onClick={() => toggleFold(line.index)}
                          aria-label={isFolded ? text.expand : text.collapse}
                          className="size-4 rounded-xs text-muted-foreground/60"
                        >
                          <ChevronRight
                            className={cn(
                              "size-3 transition-transform motion-reduce:transition-none",
                              !isFolded && "rotate-90",
                            )}
                          />
                        </Button>
                      ) : null}
                    </td>
                    <td
                      className={cn(
                        "min-w-0 pr-4 pl-1",
                        wrap
                          ? "whitespace-pre-wrap break-words"
                          : "whitespace-pre",
                      )}
                    >
                      {line.tokens.length
                        ? line.tokens.map((token, index) => (
                            <span
                              // biome-ignore lint/suspicious/noArrayIndexKey: Tokens have no stable identity beyond their position in a line.
                              key={index}
                              style={{ color: token.color }}
                            >
                              {token.content}
                            </span>
                          ))
                        : line.content || "\u00a0"}
                      {isFolded ? (
                        <Button
                          variant="outline"
                          size="xs"
                          onClick={() => toggleFold(line.index)}
                          className="ml-2 h-4 rounded-xs px-1 text-muted-foreground text-sm"
                        >
                          {line.foldEnd - line.index} lines
                        </Button>
                      ) : null}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
        {!showSkeleton && lines.length === 0 && (
          <div className="px-4 py-4 font-mono text-muted-foreground text-sm">
            {text.empty}
          </div>
        )}
      </div>
    </GlassSurface>
  );
}

export type { ShikiProviderProps } from "@/lib/viewer/shiki-context";
export { ShikiProvider } from "@/lib/viewer/shiki-context";

"use client";

import { cn } from "cn";
import type { ClipboardStatus } from "@/hooks/use-clipboard";
import {
  type IconInput,
  type IconNode,
  MorphIcon,
  type MorphIconProps,
} from "@/components/ui/morph-icon";

const copyShape: IconNode = [
  ["rect", { width: 14, height: 14, x: 8, y: 8, rx: 2, ry: 2 }],
  ["path", { d: "M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" }],
];
const checkShape: IconNode = [["path", { d: "m20 6-11 11-5-5" }]];
const errorShape: IconNode = [["path", { d: "m18 6-12 12M6 6l12 12" }]];
const pendingShape: IconNode = [["path", { d: "M12 2a10 10 0 1 0 10 10" }]];

type CopyIconProps = Omit<
  MorphIconProps,
  "icon" | "from" | "to" | "progress"
> & {
  status?: ClipboardStatus;
  copied?: boolean;
  error?: boolean;
  pending?: boolean;
  idleIcon?: IconInput;
};

function CopyIcon({
  status,
  copied = false,
  error = false,
  pending = false,
  className,
  idleIcon = copyShape,
  ...props
}: CopyIconProps) {
  let state: ClipboardStatus = status ?? "idle";
  if (status === undefined) {
    if (error) state = "error";
    else if (pending) state = "pending";
    else if (copied) state = "copied";
  }
  const icon = {
    idle: idleIcon,
    pending: pendingShape,
    copied: checkShape,
    error: errorShape,
  }[state];
  return (
    <MorphIcon
      icon={icon}
      data-slot="copy-icon"
      data-copy-state={state}
      className={cn(
        state === "pending" && "animate-spin motion-reduce:animate-none",
        state === "error" && "text-destructive",
        className,
      )}
      {...props}
    />
  );
}

export type { CopyIconProps };
export { CopyIcon };

"use client";

import type { Monaco } from "@monaco-editor/react";
import { cn } from "cn";
import {
  Columns2,
  Eye,
  EyeOff,
  FileCode2,
  Maximize2,
  Minimize2,
} from "lucide-react";
import type { editor } from "monaco-editor";
import {
  type ComponentProps,
  type ComponentType,
  createContext,
  lazy,
  type ReactNode,
  type Ref,
  type RefObject,
  Suspense,
  type UIEvent,
  type UIEventHandler,
  useCallback,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { useClipboard } from "@/hooks/use-clipboard";
import { useFullscreen } from "@/hooks/use-fullscreen";
import { useViewerTheme } from "@/hooks/use-viewer-theme";
import { useGlassEnabled } from "@/lib/glass/context";
import type { ViewerThemes } from "@/lib/viewer/shiki";
import { useShikiThemes } from "@/lib/viewer/shiki-context";
import type { Button } from "@/components/ui/button";
import { CopyIcon } from "@/components/ui/copy-icon";
import { GlassSurface } from "@/components/ui/glass";

type ButtonSize = ComponentProps<typeof Button>["size"];

import { useEditorModelPath, useEditorValue } from "@/hooks/use-editor-state";
import { ViewerButton as TooltipButton } from "@/lib/viewer/controls";
import { HtmlViewer } from "@/components/ui/html-viewer";
import { MarkdownViewer } from "@/components/ui/markdown-viewer";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

type EditorTheme = "light" | "dark";
type MonacoEditorInstance = editor.IStandaloneCodeEditor;
export type EditorViewMode = "edit" | "preview" | "split";
export type EditorFullscreenMode = "fixed" | "screen";

type EditorToolbarSlot =
  | ReactNode
  | ((context: EditorToolbarActionContext) => ReactNode);

export interface EditorToolbarActionContext {
  value: string;
  disabled: boolean;
  language: string;
  theme: EditorTheme;
  size?: ButtonSize;
  mode: EditorViewMode;
  hasPreview: boolean;
  isSplitView: boolean;
  fullscreen: boolean;
  fullscreenMode: EditorFullscreenMode;
  editor: MonacoEditorInstance | null;
  format: () => void;
  setMode: (mode: EditorViewMode) => void;
  setFullscreen: (fullscreen: boolean) => void;
}

export type EditorLanguageOption = { value: string; label: string };

const EDITOR_LANGUAGE_NAMES: Readonly<Record<string, string>> = {
  plaintext: "Plain text",
  css: "CSS",
  go: "Go",
  html: "HTML",
  java: "Java",
  javascript: "JavaScript",
  json: "JSON",
  markdown: "Markdown",
  python: "Python",
  rust: "Rust",
  shell: "Shell",
  sql: "SQL",
  tsx: "TSX",
  typescript: "TypeScript",
  yaml: "YAML",
};
const DEFAULT_EDITOR_LANGUAGES = Object.entries(EDITOR_LANGUAGE_NAMES).map(
  ([value, label]) => ({ value, label }),
);
function normalizeEditorLanguage(value: string) {
  const id = value.trim().toLowerCase();
  if (!id) return "plaintext";
  switch (id) {
    case "ts":
      return "typescript";
    case "js":
      return "javascript";
    case "md":
      return "markdown";
    case "text":
      return "plaintext";
    default:
      return id;
  }
}
function editorLanguageLabel(value: string) {
  if (Object.hasOwn(EDITOR_LANGUAGE_NAMES, value))
    return EDITOR_LANGUAGE_NAMES[value];
  return value;
}

export interface EditorProps {
  readonly value?: string;
  readonly onChange?: (value: string) => void;
  readonly disabled?: boolean;
  readonly language?: string;
  readonly onLanguageChange?: (language: string) => void;
  readonly languages?: readonly EditorLanguageOption[];
  readonly toolbarLanguage?: boolean;
  readonly className?: string;
  readonly glass?: boolean;
  readonly defaultValue?: string;
  readonly height?: string | number;
  readonly size?: ButtonSize;
  readonly toolbar?: false | EditorToolbarSlot;
  readonly toolbarTitle?: EditorToolbarSlot;
  readonly toolbarMode?: boolean;
  readonly toolbarCopy?: boolean;
  readonly labels?: Partial<EditorLabels>;
  readonly fullscreen?:
    | false
    | {
        readonly value?: boolean;
        readonly defaultValue?: boolean;
        readonly onChange?: (fullscreen: boolean) => void;
        readonly mode?: EditorFullscreenMode;
      };
  readonly preview?: {
    readonly component: ComponentType<{
      readonly content: string;
      readonly language: string;
      readonly scrollContainerRef?: Ref<HTMLDivElement>;
      readonly onScroll?: UIEventHandler<HTMLDivElement>;
    }>;
    readonly mode?: EditorViewMode;
    readonly defaultMode?: EditorViewMode;
    readonly onModeChange?: (mode: EditorViewMode) => void;
  };
}

export type EditorLabels = {
  copied: string;
  copyFailed: string;
  loading: string;
  loadingPreview: string;
  language: string;
  error: string;
  preview: string;
  hidePreview: string;
  split: string;
  copy: string;
  fullscreen: string;
  exitFullscreen: string;
};

const DEFAULT_EDITOR_LABELS: EditorLabels = {
  copied: "Copied",
  copyFailed: "Copy failed",
  loading: "Loading editor",
  loadingPreview: "Loading preview…",
  language: "Language",
  error: "Unable to load editor",
  preview: "Preview",
  hidePreview: "Hide preview",
  split: "Split",
  copy: "Copy",
  fullscreen: "Fullscreen",
  exitFullscreen: "Exit fullscreen",
};

export function EditorToolbarButton({
  size = "icon-sm",
  variant = "ghost",
  className,
  ...props
}: Readonly<ComponentProps<typeof TooltipButton>>) {
  return (
    <TooltipButton
      size={size}
      variant={variant}
      className={cn(
        "text-muted-foreground hover:bg-background/70 hover:text-foreground [&_svg]:size-3.5",
        className,
      )}
      {...props}
    />
  );
}

const HtmlPreviewScrollContext = createContext<{
  setElement: (element: HTMLElement | null) => void;
  onScroll: (element: HTMLElement) => void;
} | null>(null);

const MonacoEditor = lazy(() => import("@/lib/editor/monaco-client"));
async function applyShadcnTheme(
  monaco: Monaco,
  theme: EditorTheme,
  element: HTMLElement,
  name: string,
  isCurrent: () => boolean,
  language: string,
  themes: ViewerThemes,
) {
  const { applyEditorTheme } = await import("@/lib/editor/monaco-theme");
  await applyEditorTheme(
    monaco,
    theme,
    element,
    name,
    isCurrent,
    language,
    themes,
  );
}

function useEditorState({
  value,
  defaultValue,
  onChange,
  disabled,
  language = "plaintext",
  theme,
  themeName,
  themes,
  rootRef,
  size,
  height,
  fullscreen,
  preview,
}: Pick<
  EditorProps,
  | "value"
  | "defaultValue"
  | "onChange"
  | "disabled"
  | "language"
  | "size"
  | "height"
  | "fullscreen"
  | "preview"
> & {
  theme: EditorTheme;
  themeName: string;
  themes: ViewerThemes;
  rootRef: RefObject<HTMLDivElement | null>;
}) {
  const { resolvedValue, handleChange } = useEditorValue({
    value,
    defaultValue,
    onChange,
    disabled,
  });
  const [uncontrolledMode, setUncontrolledMode] = useState<EditorViewMode>(
    () => {
      if (!preview) return "edit";
      return preview.defaultMode ?? "split";
    },
  );
  const PreviewComponent = preview?.component;
  const hasPreview = !!PreviewComponent;
  const controlledMode = preview?.mode;
  const onPreviewModeChange = preview?.onModeChange;
  const effectiveMode: EditorViewMode = hasPreview
    ? (controlledMode ?? uncontrolledMode)
    : "edit";
  const showEditorPane = effectiveMode !== "preview";
  const showPreviewPane = hasPreview && effectiveMode !== "edit";
  const isSplitView = showEditorPane && showPreviewPane;
  const fullscreenOption =
    typeof fullscreen === "object" ? fullscreen : undefined;
  const fullscreenMode = fullscreenOption?.mode ?? "fixed";
  const fullscreenState = useFullscreen({
    fullscreen: fullscreenOption?.value,
    defaultFullscreen: fullscreenOption?.defaultValue,
    onFullscreenChange: fullscreenOption?.onChange,
    mode: fullscreenMode,
    ref: rootRef,
  });
  const isFixedFullscreen =
    fullscreenState.fullscreen && fullscreenMode === "fixed";
  const isScreenFullscreen =
    fullscreenState.fullscreen && fullscreenMode === "screen";
  const previewScroll = useEditorPreviewScrollSync();
  const monacoEditor = useMonacoEditor({
    disabled,
    language,
    theme,
    themeName,
    themes,
    elementRef: rootRef,
    previewScroll,
  });
  const hasExplicitHeight = height !== undefined;
  const contentHeight = typeof height === "number" ? `${height}px` : height;
  const contentStyle =
    hasExplicitHeight && !fullscreenState.fullscreen
      ? { height: contentHeight }
      : undefined;
  const rootStyle =
    isFixedFullscreen && hasExplicitHeight
      ? { height: contentHeight }
      : undefined;

  const setMode = useCallback(
    (nextMode: EditorViewMode) => {
      const next = hasPreview ? nextMode : "edit";
      if (controlledMode === undefined) setUncontrolledMode(next);
      onPreviewModeChange?.(next);
    },
    [controlledMode, hasPreview, onPreviewModeChange],
  );

  useEffect(() => {
    previewScroll.setSyncEnabled(isSplitView);
  }, [isSplitView, previewScroll.setSyncEnabled]);

  const toolbarContext: EditorToolbarActionContext = {
    value: resolvedValue,
    disabled: disabled ?? false,
    language,
    theme,
    size,
    mode: effectiveMode,
    hasPreview,
    isSplitView,
    fullscreen: fullscreenState.fullscreen,
    fullscreenMode,
    editor: monacoEditor.currentEditor,
    format: monacoEditor.handleFormat,
    setMode,
    setFullscreen: fullscreenState.setFullscreen,
  };

  return {
    resolvedValue,
    rootRef: fullscreenState.ref,
    fullscreen: fullscreenState.fullscreen,
    isFixedFullscreen,
    isScreenFullscreen,
    setFullscreen: fullscreenState.setFullscreen,
    contentStyle,
    contentFillsParent: fullscreenState.fullscreen || !hasExplicitHeight,
    rootStyle,
    PreviewComponent,
    hasPreview,
    effectiveMode,
    showEditorPane,
    showPreviewPane,
    isSplitView,
    toolbarContext,
    editorRef: monacoEditor.editorRef,
    previewScroll,
    handleChange,
    handleMount: monacoEditor.handleMount,
    setMode,
  };
}

function useMonacoEditor({
  disabled,
  language,
  theme,
  themeName,
  themes,
  elementRef,
  previewScroll,
}: {
  disabled?: boolean;
  language: string;
  themes: ViewerThemes;
  theme: EditorTheme;
  themeName: string;
  elementRef: RefObject<HTMLDivElement | null>;
  previewScroll: ReturnType<typeof useEditorPreviewScrollSync>;
}) {
  const themeRef = useRef({ theme, name: themeName });
  const editorRef = useRef<MonacoEditorInstance | null>(null);
  const [currentEditor, setCurrentEditor] =
    useState<MonacoEditorInstance | null>(null);
  const monacoRef = useRef<Monaco | null>(null);
  const themeGeneration = useRef(0);
  const { scrollDisposableRef, syncPreviewFromEditor } = previewScroll;

  const updateTheme = useCallback(
    (monaco: Monaco, nextTheme: EditorTheme, name: string) => {
      const element = elementRef.current;
      if (!element) return;
      const generation = ++themeGeneration.current;
      applyShadcnTheme(
        monaco,
        nextTheme,
        element,
        name,
        () =>
          themeGeneration.current === generation &&
          elementRef.current === element &&
          element.isConnected,
        language,
        themes,
      ).catch(() => {});
    },
    [elementRef, language, themes],
  );

  useEffect(
    () => () => {
      themeGeneration.current++;
    },
    [],
  );

  useEffect(() => {
    themeRef.current = { theme, name: themeName };
  }, [theme, themeName]);

  const handleMount = useCallback(
    (editor: MonacoEditorInstance, monaco: Monaco) => {
      editorRef.current = editor;
      setCurrentEditor(editor);
      monacoRef.current = monaco;
      scrollDisposableRef.current?.dispose();
      scrollDisposableRef.current = editor.onDidScrollChange(() =>
        syncPreviewFromEditor(editor),
      );
      const currentTheme = themeRef.current;
      updateTheme(monaco, currentTheme.theme, currentTheme.name);
    },
    [scrollDisposableRef, syncPreviewFromEditor, updateTheme],
  );

  useEffect(() => {
    const monaco = monacoRef.current;
    if (monaco) updateTheme(monaco, theme, themeName);
  }, [theme, themeName, updateTheme]);

  const handleFormat = useCallback(() => {
    if (disabled) return;
    editorRef.current?.getAction("editor.action.formatDocument")?.run();
  }, [disabled]);

  return {
    editorRef,
    currentEditor,
    handleMount,
    handleFormat,
  };
}

function useEditorPreviewScrollSync() {
  const previewPaneRef = useRef<HTMLDivElement | null>(null);
  const previewScrollElementRef = useRef<HTMLElement | null>(null);
  const scrollDisposableRef = useRef<{ dispose: () => void } | null>(null);
  const syncSourceRef = useRef<"editor" | "preview" | null>(null);
  const syncEnabledRef = useRef(false);

  const setPreviewScrollElement = useCallback((node: HTMLElement | null) => {
    previewScrollElementRef.current = node;
  }, []);

  const releaseSyncLock = useCallback(() => {
    window.requestAnimationFrame(() => {
      syncSourceRef.current = null;
    });
  }, []);

  const syncPreviewFromEditor = useCallback(
    (editor: MonacoEditorInstance) => {
      if (!syncEnabledRef.current || syncSourceRef.current === "preview")
        return;
      const previewElement =
        previewScrollElementRef.current ?? previewPaneRef.current;
      if (!previewElement) return;

      const editorMaxScrollTop = Math.max(
        editor.getScrollHeight() - editor.getLayoutInfo().height,
        0,
      );
      const previewMaxScrollTop = Math.max(
        previewElement.scrollHeight - previewElement.clientHeight,
        0,
      );
      if (editorMaxScrollTop <= 0 || previewMaxScrollTop <= 0) return;

      syncSourceRef.current = "editor";
      previewElement.scrollTop =
        (editor.getScrollTop() / editorMaxScrollTop) * previewMaxScrollTop;
      releaseSyncLock();
    },
    [releaseSyncLock],
  );

  const syncEditorFromPreview = useCallback(
    (previewElement: HTMLElement, editor: MonacoEditorInstance | null) => {
      if (
        !syncEnabledRef.current ||
        syncSourceRef.current === "editor" ||
        !editor
      )
        return;

      const previewMaxScrollTop = Math.max(
        previewElement.scrollHeight - previewElement.clientHeight,
        0,
      );
      const editorMaxScrollTop = Math.max(
        editor.getScrollHeight() - editor.getLayoutInfo().height,
        0,
      );
      if (previewMaxScrollTop <= 0 || editorMaxScrollTop <= 0) return;

      syncSourceRef.current = "preview";
      editor.setScrollTop(
        (previewElement.scrollTop / previewMaxScrollTop) * editorMaxScrollTop,
      );
      releaseSyncLock();
    },
    [releaseSyncLock],
  );

  const handlePreviewScroll = useCallback(
    (event: UIEvent<HTMLDivElement>, editor: MonacoEditorInstance | null) => {
      syncEditorFromPreview(event.currentTarget, editor);
    },
    [syncEditorFromPreview],
  );

  const setSyncEnabled = useCallback((enabled: boolean) => {
    syncEnabledRef.current = enabled;
  }, []);

  useEffect(() => () => scrollDisposableRef.current?.dispose(), []);

  return {
    previewPaneRef,
    scrollDisposableRef,
    setPreviewScrollElement,
    syncPreviewFromEditor,
    handlePreviewScroll,
    syncEditorFromPreview,
    setSyncEnabled,
  };
}

export function Editor({
  value,
  onChange,
  disabled = false,
  language: requestedLanguage = "plaintext",
  onLanguageChange,
  languages = DEFAULT_EDITOR_LANGUAGES,
  toolbarLanguage = true,
  className,
  glass,
  defaultValue,
  height,
  size = "icon-sm",
  toolbar,
  toolbarTitle,
  toolbarMode = true,
  toolbarCopy = true,
  labels,
  fullscreen,
  preview,
}: Readonly<EditorProps>) {
  const glassEnabled = useGlassEnabled(glass);
  const language = normalizeEditorLanguage(requestedLanguage);
  const languageOptions = new Map<string, EditorLanguageOption>();
  for (const option of languages) {
    const value = normalizeEditorLanguage(option.value);
    if (value && !languageOptions.has(value))
      languageOptions.set(value, { value, label: option.label });
  }
  if (!languageOptions.has(language))
    languageOptions.set(language, {
      value: language,
      label: editorLanguageLabel(language),
    });
  const editorPath = useEditorModelPath(language);
  const text = { ...DEFAULT_EDITOR_LABELS, ...labels };
  const instanceId = useId()
    .replace(/[^a-zA-Z0-9-]/g, "")
    .toLowerCase();
  const rootRef = useRef<HTMLDivElement>(null);
  const [localDark, setLocalDark] = useState(false);
  useEffect(() => {
    const node = rootRef.current;
    if (!node) return;
    const resolve = () => setLocalDark(node.closest(".dark") !== null);
    resolve();
    const observer = new MutationObserver(resolve);
    for (
      let ancestor: HTMLElement | null = node;
      ancestor;
      ancestor = ancestor.parentElement
    )
      observer.observe(ancestor, {
        attributes: true,
        attributeFilter: ["class"],
      });
    return () => observer.disconnect();
  }, []);
  const themes = useShikiThemes();
  const { resolvedTheme: appTheme } = useViewerTheme();
  const resolvedTheme = localDark ? "dark" : appTheme;
  // Keep the registered name stable while the async Shiki theme is rebuilt.
  // Monaco's React wrapper applies a changed `theme` prop synchronously.
  const themeName = `editor-${instanceId}`;
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  const editor = useEditorState({
    value,
    defaultValue,
    onChange,
    disabled,
    language,
    theme: resolvedTheme,
    themeName,
    themes,
    rootRef,
    size,
    height,
    fullscreen,
    preview:
      preview ??
      {
        html: { component: HtmlEditorPreview, defaultMode: "edit" as const },
        markdown: {
          component: MarkdownEditorPreview,
          defaultMode: "edit" as const,
        },
      }[language],
  });
  const { status: copyStatus, copy } = useClipboard(editor.resolvedValue);
  const PreviewComponent = editor.PreviewComponent;
  const defaultToolbarTitle = editorLanguageLabel(language);
  const previewModeActive = editor.effectiveMode === "preview";
  let copyTooltip = text.copy;
  if (copyStatus === "copied") {
    copyTooltip = text.copied;
  } else if (copyStatus === "error") {
    copyTooltip = text.copyFailed;
  }

  return (
    <div
      data-slot="editor"
      {...(editor.isFixedFullscreen
        ? { role: "dialog", "aria-modal": true, "aria-label": text.fullscreen }
        : {})}
      ref={editor.rootRef}
      className={cn(
        "min-h-0 w-full min-w-0",
        editor.contentFillsParent && "h-full",
        editor.isScreenFullscreen && "bg-background",
        className,
      )}
      style={editor.rootStyle}
    >
      <GlassSurface
        glass={glassEnabled}
        data-slot="editor-surface"
        className={cn(
          "flex min-h-0 w-full flex-col overflow-hidden rounded-2xl bg-muted/80 text-foreground text-sm ring-1 ring-border",
          editor.contentFillsParent && "h-full min-h-0",
          editor.isFixedFullscreen &&
            "fixed inset-0 z-50 h-full rounded-none border-0",
          editor.isScreenFullscreen && "h-screen rounded-none border-0",
        )}
      >
        {toolbar !== false && (
          <div className="flex min-h-10 shrink-0 flex-wrap items-center gap-x-2 gap-y-1 border-border/70 border-b bg-muted/80 px-3 py-1">
            <FileCode2
              aria-hidden="true"
              className="size-3.5 shrink-0 text-muted-foreground/70"
            />
            <span
              className={cn(
                "min-w-0 truncate font-medium font-mono text-foreground/80 text-sm",
                "min-w-20 flex-1",
              )}
            >
              {typeof toolbarTitle === "function"
                ? (toolbarTitle(editor.toolbarContext) ?? defaultToolbarTitle)
                : (toolbarTitle ?? defaultToolbarTitle)}
            </span>
            <div className="ml-auto flex shrink-0 flex-wrap items-center justify-end gap-1">
              {toolbarLanguage && onLanguageChange && (
                <Select
                  value={language}
                  disabled={disabled || languageOptions.size < 2}
                  items={Object.fromEntries(
                    [...languageOptions].map(([value, option]) => [
                      value,
                      option.label,
                    ]),
                  )}
                  onValueChange={(next) => {
                    if (next !== null && next !== language)
                      onLanguageChange(next);
                  }}
                >
                  <SelectTrigger
                    type="button"
                    size="sm"
                    aria-label={text.language}
                    className="max-w-36 bg-transparent text-muted-foreground"
                  >
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {[...languageOptions.values()].map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
              {typeof toolbar === "function"
                ? toolbar(editor.toolbarContext)
                : toolbar}
              {editor.hasPreview && toolbarMode && (
                <>
                  <EditorToolbarButton
                    size={size}
                    variant={previewModeActive ? "secondary" : "ghost"}
                    tooltip={
                      previewModeActive ? text.hidePreview : text.preview
                    }
                    onClick={() =>
                      editor.setMode(previewModeActive ? "edit" : "preview")
                    }
                  >
                    {previewModeActive ? <EyeOff /> : <Eye />}
                  </EditorToolbarButton>
                  <EditorToolbarButton
                    size={size}
                    variant={editor.isSplitView ? "secondary" : "ghost"}
                    tooltip={text.split}
                    onClick={() =>
                      editor.setMode(
                        editor.effectiveMode === "split" ? "edit" : "split",
                      )
                    }
                  >
                    <Columns2 />
                  </EditorToolbarButton>
                </>
              )}
              {toolbarCopy && (
                <EditorToolbarButton
                  size={size}
                  variant="ghost"
                  tooltip={copyTooltip}
                  disabled={disabled || copyStatus === "pending"}
                  onClick={() => void copy(editor.toolbarContext.value)}
                >
                  <CopyIcon
                    status={copyStatus}
                    className={cn(
                      copyStatus === "copied" && "text-primary",
                      copyStatus === "error" && "text-destructive",
                    )}
                  />
                </EditorToolbarButton>
              )}
              {fullscreen !== false && (
                <EditorToolbarButton
                  size={size}
                  variant="ghost"
                  tooltip={
                    editor.fullscreen ? text.exitFullscreen : text.fullscreen
                  }
                  onClick={() => editor.setFullscreen(!editor.fullscreen)}
                >
                  {editor.fullscreen ? <Minimize2 /> : <Maximize2 />}
                </EditorToolbarButton>
              )}
            </div>
          </div>
        )}
        <div
          className={cn(
            "flex min-h-0",
            editor.contentFillsParent && "flex-1",
            editor.isSplitView && "divide-x divide-input",
          )}
          style={editor.contentStyle}
        >
          {editor.showEditorPane && (
            <div
              className={cn(
                "min-w-0 flex-1",
                editor.isSplitView ? "w-1/2" : "w-full",
              )}
            >
              {mounted ? (
                <Suspense
                  fallback={
                    <div className="size-full animate-pulse bg-muted motion-reduce:animate-none" />
                  }
                >
                  <MonacoEditor
                    key={editorPath}
                    loading={
                      <div
                        role="status"
                        className="size-full animate-pulse bg-muted motion-reduce:animate-none"
                      >
                        {text.loading}
                      </div>
                    }
                    errorLabel={text.error}
                    height="100%"
                    language={language}
                    path={editorPath}
                    value={editor.resolvedValue}
                    theme={themeName}
                    themeMode={resolvedTheme}
                    shikiThemes={themes}
                    themeElement={rootRef}
                    onMount={editor.handleMount}
                    onChange={(nextValue) =>
                      editor.handleChange(nextValue ?? "")
                    }
                    options={{
                      minimap: { enabled: false },
                      fontSize: 14,
                      lineNumbers: "on",
                      roundedSelection: false,
                      scrollBeyondLastLine: false,
                      scrollbar: {
                        vertical: "auto",
                        horizontal: "auto",
                        useShadows: false,
                        verticalScrollbarSize: 10,
                        horizontalScrollbarSize: 10,
                      },
                      automaticLayout: true,
                      readOnly: disabled,
                      domReadOnly: disabled,
                      padding: { top: 8, bottom: 8 },
                    }}
                  />
                </Suspense>
              ) : (
                <div
                  className="size-full animate-pulse bg-muted motion-reduce:animate-none"
                  role="status"
                  aria-label={text.loading}
                />
              )}
            </div>
          )}

          {editor.showPreviewPane && PreviewComponent && (
            <div
              ref={editor.previewScroll.previewPaneRef}
              onScroll={(event) =>
                editor.previewScroll.handlePreviewScroll(
                  event,
                  editor.editorRef.current,
                )
              }
              className={cn(
                "h-full overflow-auto bg-background [scrollbar-color:transparent_transparent] [scrollbar-width:thin] hover:[scrollbar-color:var(--editor-scrollbar-thumb)_transparent] [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-muted-foreground/35 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar]:size-2",
                editor.isSplitView ? "w-1/2" : "w-full",
              )}
            >
              <Suspense
                fallback={
                  <div className="animate-pulse p-4 text-muted-foreground text-sm motion-reduce:animate-none">
                    {text.loadingPreview}
                  </div>
                }
              >
                <HtmlPreviewScrollContext.Provider
                  value={{
                    setElement: editor.previewScroll.setPreviewScrollElement,
                    onScroll: (element) =>
                      editor.previewScroll.syncEditorFromPreview(
                        element,
                        editor.editorRef.current,
                      ),
                  }}
                >
                  <PreviewComponent
                    content={editor.resolvedValue}
                    language={language}
                    scrollContainerRef={
                      editor.previewScroll.setPreviewScrollElement
                    }
                    onScroll={(event) =>
                      editor.previewScroll.handlePreviewScroll(
                        event,
                        editor.editorRef.current,
                      )
                    }
                  />
                </HtmlPreviewScrollContext.Provider>
              </Suspense>
            </div>
          )}
        </div>
      </GlassSurface>
    </div>
  );
}

function HtmlEditorPreview({ content }: Readonly<{ content: string }>) {
  const port = useContext(HtmlPreviewScrollContext);
  const frameRef = useRef<HTMLIFrameElement>(null);
  const [previewDocument, setPreviewDocument] = useState<Document | null>(null);
  useEffect(() => {
    const element =
      previewDocument?.scrollingElement ?? previewDocument?.documentElement;
    if (
      !port ||
      !previewDocument ||
      !element ||
      element.namespaceURI !== "http://www.w3.org/1999/xhtml"
    )
      return;
    const scrollElement = element as HTMLElement;
    port.setElement(scrollElement);
    const scroll = () => port.onScroll(scrollElement);
    previewDocument.addEventListener("scroll", scroll, {
      passive: true,
      capture: true,
    });
    previewDocument.defaultView?.addEventListener("scroll", scroll, {
      passive: true,
    });
    return () => {
      port.setElement(null);
      previewDocument.removeEventListener("scroll", scroll, true);
      previewDocument.defaultView?.removeEventListener("scroll", scroll);
    };
  }, [port, previewDocument]);
  return (
    <HtmlViewer
      ref={frameRef}
      content={content}
      sandbox="allow-same-origin"
      onLoad={() => {
        try {
          setPreviewDocument(frameRef.current?.contentDocument ?? null);
        } catch {
          setPreviewDocument(null);
        }
      }}
    />
  );
}

