            typeof elementProps.href === "string" &&
            elementProps.href.startsWith("#")
              ? undefined
              : "noopener noreferrer"
          }
          target={
            typeof elementProps.href === "string" &&
            elementProps.href.startsWith("#")
              ? undefined
              : "_blank"
          }
