    task = import("monaco-editor/languages/features/json/register").then(
      (json) => {
        workers.registerReset("json", () =>
          json.jsonDefaults.setDiagnosticsOptions(
            json.jsonDefaults.diagnosticsOptions,
          ),
        );
      },
    );
